    "result": "ie_ptr",
    "a2": "buf_len",
    "a3": "out_len",
    "v3": "buf_end",
    "v4": "ie_len",
    "v5": "next_ie"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "information element ID / TLV tag byte"
    },
    {
      "offset": 1,
      "meaning": "information element / TLV payload length"
    },
    {
      "offset": 2,
      "meaning": "payload start after the 2-byte header"
    }
  ]
